protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
        // Existing 500K documents use "Discriminator", and direct SQL queries reference it.
        entity.HasDiscriminator<string>("Discriminator");

        // EF Core 9 no longer prefixes id with the discriminator.
        // Existing documents have ids like "Product|123"; preserve that format.
        entity.HasRootDiscriminatorInJsonId(true);
    });

    // HasIndex was removed — Cosmos DB indexing is managed via the container's
    // indexing policy (Azure Portal / Bicep / Terraform), not through EF Core.
}

